const setDefaultWarehouse = (frm) => {
	if (frm.is_new() && !frm.doc.set_warehouse && frm.doc.company) {
		frappe.db.get_value('Company', frm.doc.company, 'abbr')
			.then(r => {
				if (r?.message?.abbr) {
					frm.set_value(
						'set_warehouse',
						`Stores - ${r.message.abbr}`
					);
				}
			});
	}
};

frappe.ui.form.on('Sales Invoice', {
	onload(frm) {
		setDefaultWarehouse(frm);
	}
});

const setDefaultWarehouse = (frm) => {
	if (frm.is_new() && !frm.doc.set_warehouse && frm.doc.company) {
		frappe.db.get_value('Company', frm.doc.company, 'abbr')
			.then(r => {
				if (r?.message?.abbr) {
					frm.set_value(
						'set_warehouse',
						`Stores - ${r.message.abbr}`
					);
				}
			});
	}
};

frappe.ui.form.on('Purchase Invoice', {
	onload(frm) {
		setDefaultWarehouse(frm);
	}
});

frappe.ui.form.on('Customer', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Customer GL PDF'), () => {

                const default_company = frm.doc.company || frappe.defaults.get_user_default("Company");

                const d = new frappe.ui.Dialog({
                    title: 'Select Date Range for GL PDF',
                    fields: [
                        {
                            fieldtype: 'Date',
                            label: 'From Date',
                            fieldname: 'from_date',
                            default: frappe.datetime.year_start()
                        },
                        {
                            fieldtype: 'Date',
                            label: 'To Date',
                            fieldname: 'to_date',
                            default: frappe.datetime.year_end()
                        },
                        {
                            fieldtype: 'Link',
                            label: 'Company',
                            fieldname: 'company',
                            options: 'Company',
                            default: default_company,
                            reqd: 1
                        }
                    ],
                    primary_action_label: 'Download PDF',
                    primary_action(values) {
                        d.hide();

                        // Build API URL with query params
                        const url = `/api/method/bemantech.api.customer_gl_pdf.download?customer=${encodeURIComponent(frm.doc.name)}&company=${encodeURIComponent(values.company)}&from_date=${values.from_date}&to_date=${values.to_date}`;

                        // Open PDF in new tab
                        window.open(url, '_blank');
                    }
                });

                d.show();
            }, __('View'));
        }
    }
});
